const SCALE_FACTOR = 20;
const LOCAL_STORAGE_SAVE_KEY = "oooooo-savedata";

export default {
    setup() {
		const pages = ref(Array.from({length: VECTORS.length}).map((_, i) => i));
		const currentPage = ref(0);
		const leftCadiates = ref([]);
		const rightCadiates = ref([]);

		onMounted(() => {
			renderPage(0);
			nextTick(() => {
				drawNext();
			});
		});

		let lastDrawTime = new Date();
		let newPath = true;
		function drawNext() {
			let time = new Date();

			//绘制所有的候选项
			for (let item of leftCadiates.value) {
				let ctx = document.getElementById(`sw-p-${item.i}`).getContext("2d");
				let radius = item.radius * SCALE_FACTOR;
				draw(time, ctx, null, [item], radius + 5, radius + 5);
			}
			for (let item of rightCadiates.value) {
				let ctx = document.getElementById(`sw-p-${item.i}`).getContext("2d");
				let radius = item.radius * SCALE_FACTOR;
				draw(time, ctx, null, [item], radius + 5, radius + 5);
			}

			//绘制左右两边的数据
			let lCtx = document.getElementById('left-frame').getContext("2d");
			let lCtx2 = document.getElementById('left-frame-path').getContext("2d");
			draw(time, lCtx, lCtx2, leftCadiates.value, 150, 150, newPath);
			let rCtx = document.getElementById('right-frame').getContext("2d");
			let rCtx2 = document.getElementById('right-frame-path').getContext("2d");
			draw(time, rCtx, rCtx2, rightCadiates.value, 150, 150, newPath);
			newPath = false;

			window.requestAnimationFrame(drawNext);
		}

		function draw(time, ctx, ctx2, drawItems, x, y, clearCtx2 = false) {
			ctx.save();
			ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height); //clear canvas
			ctx.strokeStyle = "rgba(0, 120, 0, 1)";
			if (ctx2) ctx2.strokeStyle = "rgba(180, 255, 180, 1)";
			ctx.lineWidth = 1;
			// move to center
			ctx.translate(x, y);
			ctx.beginPath();
			ctx.arc(0, 0, 2, 0, 2 * Math.PI);
			ctx.fillStyle = "red";
			ctx.fill();

			if (ctx2) {
				ctx2.save();
				if (clearCtx2) {
					ctx2.clearRect(0, 0, 300, 300); // clear canvas
					ctx2.beginPath();
				}
				ctx2.translate(x, y);
			}

			for (let i in drawItems) {
				drawVectorAndTranslate(ctx, ctx2, drawItems[i], time,  i == drawItems.length - 1);
			}
			ctx.restore();
			if (ctx2) ctx2.restore();
		}

		function drawVectorAndTranslate(ctx, ctx2, vector, time, lastOne) {
			let radius = vector.radius * SCALE_FACTOR;
			//console.log(vector);
			let angle = 10 * vector.speed * (((2 * Math.PI) / 60) * time.getSeconds() + ((2 * Math.PI) / 60000) * time.getMilliseconds()) + vector.offset * Math.PI / 180;
			ctx.rotate(-angle);
			//console.log(angle);
			ctx.beginPath();
			ctx.moveTo(0, 0);
			ctx.lineTo(radius, 0);
			ctx.stroke();
			//ctx.save();
			//ctx.strokeStyle = "rgba(0, 120, 0, 0.5)";
			ctx.beginPath();
			ctx.arc(0, 0, radius, 0, 2 * Math.PI);
			ctx.stroke();
			//ctx.restore();
			ctx.translate(radius, 0);
			ctx.rotate(angle);

			if (ctx2) {
				//console.log(time);
				//console.log('time is  ' + time + " last draw is " + lastDraw);
				ctx2.rotate(-angle);
				ctx2.translate(radius, 0);
				ctx2.rotate(angle);
				if (lastOne) {
					if (time - lastDrawTime > 50)
					{
						ctx2.beginPath();
					}
					ctx2.lineTo(0, 0);
					ctx2.stroke();
					lastDrawTime = time;
				}
			}
		}

		const renderPage = (page) => {
			//载入本地存档
			let saveData = {};
			let saveDataString = localStorage.getItem(LOCAL_STORAGE_SAVE_KEY);
			if (saveDataString) {
				saveData = JSON.parse(saveDataString);
			}

			//筛选本题数据
			let rightSave = [];
			if (saveData[page]) {
				rightSave = saveData[page];
			}
			let problem = VECTORS[page];
			leftCadiates.value = problem.filter(x => rightSave.indexOf(x.label) === -1);
			rightCadiates.value = problem.filter(x => rightSave.indexOf(x.label) !== -1);

			currentPage.value = page;
			newPath = true;
		}

		let dragging = null;
		let dragDir = -1;
		const drag = (item, dir) => {
			if (dir === 0 && leftCadiates.value.indexOf(item) === 0) {
				return false;
			}

			dragging = item;
			dragDir = dir;
		}
		const drop = (target) => {
			if (dragging && dragDir !== target) {
				//从原来的框中删掉该元素
				const removeItem = (c, i) => c.value.splice(c.value.indexOf(i), 1);
				if (dragDir === 0) {
					removeItem(leftCadiates, dragging);
				} else if (dragDir === 1) {
					removeItem(rightCadiates, dragging);
				}

				//插入目标一侧
				if (target === 0) {
					leftCadiates.value.push(dragging);
				} else {
					rightCadiates.value.push(dragging);
				}

				//保存到本地存档中
				let saveData = {};
				let saveDataString = localStorage.getItem(LOCAL_STORAGE_SAVE_KEY);
				if (saveDataString) {
					saveData = JSON.parse(saveDataString);
				}
				if (target == 0) {
					if (saveData[currentPage.value]) {
						let ii = saveData[currentPage.value].indexOf(dragging.label);
						if (ii !== -1) {
							saveData[currentPage.value].splice(ii, 1);
						}
					}
				} else {
					if (!saveData[currentPage.value]) {
						saveData[currentPage.value] = [];
					}
					saveData[currentPage.value].push(dragging.label);
				}
				localStorage.setItem(LOCAL_STORAGE_SAVE_KEY, JSON.stringify(saveData));
			}

			dragging = null;
			dragDir = -1;
			newPath = true;
		}

        return {
            pages,
            currentPage,
			renderPage,
			leftCadiates,
			rightCadiates,
			drag,
			drop
        };
    },
	components: {
		SingleWord: (props) => {
			const item = props.item;
			const radius = item.radius * SCALE_FACTOR;
			const width = radius * 2 + 10;

			let canvas = h('canvas', { width: width, height: width, draggable: false, id: `sw-p-${item.i}` });
			return canvas;
		}
	}
